	\label{def:finite_embedding}


Let $S$ be a finite set of prime numbers.
We define the \emph{finite embedding} of $\mathbb{Q}$ into $\mathbb{R} \times \prod_{p \in S} \mathbb{Q}_p$ as the diagonal map.

\label{thm:existence}



	Let $(a_i)_{i \in I}$ be a finite family of nonzero rational numbers, and let
	$e_{i,v} \in \{\pm 1\}$ for each $i \in I$ and each place $v$ of $\mathbb{Q}$. There exists a rational
	number $x \in \mathbb{Q}^\times$ such that
	\[
	\forall i \in I, \forall v \text{ place of } \mathbb{Q}, (x,a_i)_v=e_{i,v}
	\]
	if and only if the following conditions hold:
	\begin{enumerate}
		\item For each $i \in I$, we have $e_{i,v}=1$ for all but finitely many places $v$.
		\item For each $i \in I$, we have $\prod_v e_{i,v}=1$.
		\item For each place $v$, there exists $x_v \in \mathbb{Q}_v^\times$ such that
		$(x_v, a_i)_v = e_{i,v}$ for all $i \in I$.
	\end{enumerate}

\[
	\forall i \in I, \forall v \text{ place of } \mathbb{Q}, (x,a_i)_v=e_{i,v}
	\]

\label{def:quadratic_form}

Let $M$ be a module over a commutative ring $A$. A function $f : M \to A$ is called a \emph{quadratic form} on $M$ if
\begin{enumerate}
\item $f(ax) = a^2f(x)$ for all $a \in A, x \in M$,
\item The function $(x, y) \mapsto f(x + y) - f(x) - f(y)$ is a bilinear form.
\end{enumerate}

\label{def:discr}


Let $p$ be a prime number and let $f$ be a quadratic form of rank $n$ over $\mathbb{Q}_p$. Take a diagonal quadratic form $a_1X_1^2 + \cdots + a_nX_n^2$ which is equivalent to $f$; then the \emph{discriminant} of $f$ is the element $d(f) = a_1 \cdots a_n \in \mathbb{Q}_p^\times/{\mathbb{Q}_p^\times}^2$.

